    "id": "r-meeting-1",
    "kind": "reading",
    "level": 5,
    "passage": "公司以前每天都开很长的会议，但是有些问题在会议结束后仍然没有解决。新经理发现，大家常常花很多时间介绍情况，却很少讨论具体的解决方法。他要求员工在开会前先准备有关信息，会议中只讨论需要决定的问题。一个月后，会议时间缩短了，工作效率却提高了。",
