    "id": "r-environment2-1",
    "kind": "reading",
    "level": 5,
    "passage": "有些人认为，保护环境需要花很多钱，所以个人的力量十分有限。其实，日常生活中有很多简单的方法可以减少浪费。例如，购买食品前先考虑自己实际需要的数量，就能减少买得太多而不得不扔掉的情况。如果很多人都养成这样的习惯，小小的改变也可以带来明显的效果。",
    "title": "An environmental change",
    "translation": "Some think environmental protection costs much money and individuals have little power. In fact, simple daily methods reduce waste. Considering how much food is really needed before buying can prevent excess food being discarded. When many adopt this habit, small changes can have noticeable effects.",
