    "title": "Product quality",
    "passage": "一家工厂为了增加产量，一度要求员工加快工作速度。虽然每天生产的商品多了，但有问题的商品也明显增加。经理发现，这些商品不仅需要重新处理，还影响了客户对公司的信任。他决定重新制定工作标准，不再只根据生产数量来评价员工的表现。",
